		},
	},
})

Translate("ruRU", "hive-regal", {
	title = "Улей Регал",
	sections = {
		{
			title = "Обзор",
			text = [=[Улей Регал — южный улей {link:silithus}Силитус{/link}а. Его норокопы, засадники, огнеплюи и рабовладельцы подчиняются властителю Ксил'ксиксу. {link:dwarves}Дворфы{/link} {link:explorers-league}Лиги исследователей{/link} вошли в него в поисках реликвий и нашли кристалл с глифами. Жрица из ночных эльфов, {link:natalia-mar-alith}Наталия Мар'алит{/link}, прижалась к нему щекой и впала в транс. Несколько недель спустя она бежала обратно в улей, и силитиды расступились, чтобы пропустить ее. Наружу она не вышла.]=],
		},
	},
})

Translate("ruRU", "bronzebeard-encampment", {
	title = "Лагерь Бронзоборода",
	aliases = { "Лагерь Бронзоборода", "лагерь Бронзоборода" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Бронзоборода — лагерь {link:explorers-league}Лиги исследователей{/link} на дальнем юге {link:silithus}Силитус{/link}а. {link:brann-bronzebeard}Бранн Бронзобород{/link} привел сюда своих копателей искать в ульях утраченные артефакты. Теперь его нет, и лагерь держат только {link:rutgar-glyphshaper}Рутгар Резчик Символов{/link}, {link:frankal-stonebridge}Франкал Каменный Мост{/link} и {link:glibb}Глибб{/link}, обезьянка пропавшего предводителя. Они просили {link:ironforge}Стальгорн{/link} прислать армию, чтобы помочь им войти в ульи. Стальгорн не ответил. За лагерем поднимаются южные горы, где охотится {link:ogres}огр{/link}омный скорпид.]=],
		},
	},
})

Translate("ruRU", "the-crystal-vale", {
	title = "Долина Кристаллов",
	aliases = { "Долина Кристаллов", "Разоренный Сумеречный лагерь" },
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Кристаллов лежит в северо-западном углу {link:silithus}Силитус{/link}а. По ней свободно бродят элементали воздуха и земли. Некогда здесь стоял лагерь {link:twilight-s-hammer}Сумеречного Молота{/link}. Теперь это место отмечают лишь разбросанные доски и холст да обломки глиняной таблички, п{link:ogres}огр{/link}ебенные в песке. Табличка рассказывает о северном лагере, первом, который завершил свой камень ветра. Бюллетень культа рассказывает о северном лагере, который уничтожил один из повелителей, вызванных его же членами. На краю разоренного поля ждет верховный лорд и говорит о Принце Воздуха.]=],
		},
	},
})

Translate("ruRU", "twilight-base-camp", {
	title = "Сумеречный лагерь",
	aliases = { "Сумеречная застава", "Сумеречный форт" },
	sections = {
		{
			title = "Обзор",
			text = [=[{link:twilight-s-hammer}Сумеречный Молот{/link} держит три лагеря в западной половине {link:silithus}Силитус{/link}а: один к западу от Крепости Кенария, один дальше на запад и один на юго-западе, близ Стены Скарабея. В каждом сектанты воздвигли камни ветра, малые и большие, через которые они говорят со знатью элементалей из {link:shadow-council}Совет{/link}а Бездны. Сумеречные хранители берегут главы тайного лексикона культа, геолорды ведут обряды, а пророки проповедуют о Последних днях. {link:krueg-skullsplitter}Круг{/link} подозревает, что лагеря связаны с пульсирующими красными кристаллами по всей пустыне.]=],
		},
	},
})

Translate("ruRU", "twilight-s-run", {
	title = "Сумеречная пещера",
	sections = {
		{
			title = "Обзор",
			text = [=[Сумеречная пещера укрыта в северо-восточном углу {link:silithus}Силитус{/link}а. Это оплот {link:twilight-s-hammer}Сумеречного Молота{/link} и логово, где обитает {link:vyral-the-vile}Вирал Мерзкий{/link}, здешний предводитель культа. Ее туннели стерегут властители и огненные разорители культа. {link:krueg-skullsplitter}Круг{/link} обнаружил ее лишь после своих первых ударов по геолордам западных лагерей.]=],
		},
	},
})

Translate("ruRU", "ortell-s-hideout", {
	title = "Укрытие Ортелла",
	sections = {
		{
			title = "Обзор",
			text = [=[В горах к югу от Деревни Южного Ветра человек прячется от своих прежних братьев. {link:hermit-ortell}Ортелл{/link} некогда состоял в {link:twilight-s-hammer}Сумеречном Молоте{/link}. Он дезертировал, и культ с тех пор охотится на него. Он живет там отшельником и встречает каждого чужака с подозрением. Однако те, кто приносит ему слово против культа, могут найти в нем полезного друга.]=],
		},
	},
})

Translate("ruRU", "bones-of-grakkarond", {
	title = "Кости Граккаронда",
	aliases = { "Граккаронд" },
	sections = {
		{
			title = "Обзор",
			text = [=[К югу от Крепости Кенария в песке лежат выбеленные кости {link:ogres}огр{/link}омного дракона. Глифы ульев показывают подобное место: посланник народа киражи встречается с тремя повелителями силитидов у костей большого дракона. {link:geologist-larksbane}Геолог Ларксбейн{/link} полагает, что верные глифы, начертанные здесь на песке, вызовут повелителей ульев и их посланника из укрытия. Ни одна запись не говорит, кем был Граккаронд и как этот дракон умер в этой пустыне.]=],
		},
	},
})

Translate("ruRU", "qiraji", {
	title = "Киражи",
	aliases = { "Силитиды" },
	sections = {
		{
			title = "Обзор",
			text = [=[Киражи — древний, мыслящий народ насекомых из южной пустыни. Они построили крепость Ан'Кираж в {link:silithus}Силитус{/link}е и оттуда повелевают силитидами — роящимися насекомыми, которые заполняют ульи этой земли. Силитидам нет числа, и каждый час вылупляются новые. Киражи — их хозяева: не звери, а интриганы, с собственными генералами и царями.]=],
		},
		{
			title = "Истоки",
			text = [=[Древнейшие предания {link:kalimdor}Калимдор{/link}а рассказывают об акирах — империи насекомых, которая воевала с древними троллями. Когда этот народ отбросили, часть его отступила на юг, в землю, которая станет {link:silithus}Силитус{/link}ом, и там стала народом киражи. Книга ночных эльфов о войне говорит, что киражи некогда боролись за господство над большей частью Калимдора.]=],
		},
		{
			title = "Рой",
			text = [=[Силитиды не действуют сами по себе. В каждом из трех ульев стоит кристалл с глифами, и ученые {link:krueg-skullsplitter}Круг{/link}а Кенария полагают, что киражи и иные, пока неведомые силы шлют через них свои послания рою. У каждого улья есть свой властитель, и властители собираются, когда их зовут глифы.]=],
		},
		{
			title = "Сила в храме",
			text = [=[Во время Войны Зыбучих песков дракон Аригос ощутил странную, смутную магию в великом храме Ан'Киража. Никто из драконов не смог добраться до ее источника. Они пришли к мысли, что нечто там управляет не только силитидами, но и самими киражи. Ночная эльфийка, коснувшаяся кристалла с глифами, тысячу лет спустя дала этому имя: {red:c-thun}К'Тун{/red}.]=],
		},
	},
})

Translate("ruRU", "war-of-the-shifting-sands", {
	title = "Война Зыбучих песков",
	sections = {
		{
			title = "Обзор",
			text = [=[Война Зыбучих песков шла почти тысячу лет назад между {link:night-elves}ночными эльфами{/link} и народом {link:qiraji}киражи{/link} из Ан'Киража. Она закончилась не победой, а тюрьмой.]=],
		},
		{
			title = "Вторжение",
			text = [=[Из Ан'Киража киражи выступили под началом генерала Раджакса, и за ними шли бесконечные рои силитидов. {link:fandral-staghelm}Фэндрал Олений Шлем{/link} собрал против них армии ночных эльфов, и его сын {link:valstann-staghelm}Валстанн{/link} сражался рядом с ним. Книга ночных эльфов о войне говорит, что отец приказал сыну удерживать Деревню Южного Ветра. Дневник, найденный в ее руинах, рассказывает больше: Императоры-близнецы Ан'Киража устроили там ловушку, Валстанн был схвачен, и Раджакс предал его смерти на глазах у армии его отца. Война длилась месяцами. {link:nak}Нак{/link}онец весь {link:silithus}Силитус{/link} был потерян, и разбитую армию ночных эльфов оттеснили через {link:un-goro-crater}Ун'Горо{/link} к {link:tanaris}Танарису{/link}.]=],
		},
		{
			title = "Драконы",
			text = [=[Там, смирившись, {link:fandral-staghelm}Фэндрал{/link} пошел к бронзовому дракону Анахроносу, сыну {red:nozdormu}Ноздорму{/red}, и молил о помощи бронзовых драконов. Анахронос отказывал, пока киражи не осмелились напасть на {link:caverns-of-time}Пещеры Времени{/link}. Даже бронзовые драконы не смогли сдержать рой, и тогда Анахронос воззвал к детям других Аспектов. Меритра пришла от рода, который ведет {red:ysera}Изера{/red}, Келестраз — от рода, который ведет {link:alexstrasza}Алекстраза{/link}, а Аригос — от рода, который ведет {red:malygos}Малигос{/red}. Высоко над Ан'Киражем они увидели, что никакая сила не окончит эту войну. Они решили запечатать врага в его собственном городе.]=],
		},
		{
			title = "Стена и скипетр",
			text = [=[Черпая силу и ночных эльфов, и драконов, они воздвигли вокруг Ан'Киража великую преграду. Меритра, Келестраз и Аригос бросились на врага, чтобы выиграть время, пока Анахронос и {link:fandral-staghelm}Фэндрал{/link} запечатывали врата. Когда дело было сделано, Анахронос дал верховному друиду скипетр, который мог снова открыть преграду. Верховный друид, скорбя о сыне, швырнул его о преграду и разбил. Анахронос собрал осколки и отдал их на хранение четырем великим родам драконов, чтобы никто не мог легко сделать скипетр целым.]=],
		},
	},
})

Translate("ruRU", "abyssal-council", {
	title = "Совет Бездны",
	aliases = { "Совет Бездны", "Высший совет Бездны" },
	sections = {
		{
			title = "Обзор",
			text = [=[Совет Бездны — иерархия знати элементалей, которой {link:twilight-s-hammer}Сумеречный Молот{/link} служит в {link:silithus}Силитус{/link}е. Культ зовет их своими господами и говорит с ними через камни ветра в своих лагерях. {link:cenarion-circle}Круг Кенария{/link} узнал, что совет управляет культом через эти камни и что сектанты получают от него приказы.]=],
		},
		{
			title = "Ранги",
			text = [=[Внизу стоят храмовники: багровые, лазурные, седые и земляные. Над ними — четыре {link:duke-nicholas-zverenhoff}герцог{/link}а: герцог Синдерс, герцог Глубин, герцог Зефиров и герцог Осколков. Наверху восседает Высший совет из четырех повелителей: принц Скальдренокс, верховный маршал Вихраксис, барон Казум и лорд Сквол.]=],
		},
		{
			title = "Камни ветра",
			text = [=[Собственные правила культа строги. Посвященные могут вызвать храмовника, но должны быть в надлежащем облачении, иначе пробудится защита камня. Говорить с {link:duke-nicholas-zverenhoff}герцог{/link}ом могут лишь те, кто несет медальон положения. Взывать к Высшему совету могут только Сумеречные лорды, а всякого чужака, который попытается, велено сжечь дотла. Мастерица {link:krueg-skullsplitter}Круг{/link}а научилась ковать такие медальоны. С медальоном и в облачении самого культа отважный боец может вызвать знатного элементаля совета из камня и сразить его.]=],
		},
	},
})

Translate("ruRU", "commander-mar-alith", {
	title = "Командир Мар'алит",
	subtitle = "Командир Крепости Кенария",
	found = "Крепость Кенария",
	hint = "Поговорите с командиром, который держит Крепость Кенария.",
	allegiance = "Круг Кенария · Крепость Кенария",
	aliases = { "Мар'алит" },
	sections = {
		{
			title = "Обзор",
			text = [=[Командир Мар'алит ведет силы {link:cenarion-circle}Круга Кенария{/link} в Крепости Кенария. Его задача — удержать сердце {link:silithus}Силитус{/link}а против силитидов и сломить хватку, которой {link:twilight-s-hammer}Сумеречный Молот{/link} держит пустыню. Он исполняет свой долг, но мысли его далеко. Его возлюбленная {link:natalia-mar-alith}Наталия{/link} исчезла, а он долгом привязан к своему посту. Он не может понять, почему это обрушилось на него сейчас, когда еще так много предстоит сделать.]=],
		},
		{
			title = "Значение",
			text = [=[Мар'алит первым ощутил цену возвращения {link:krueg-skullsplitter}Круг{/link}а в {link:silithus}Силитус{/link}. Те самые ульи, с которыми его послали сражаться, отняли у него женщину, которую он любит. Через его утрату Круг узнает имя силы, стоящей за роем.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он командует Крепостью Кенария и ее солдатами.
• Он получает расшифрованные тайны Сумеречного Молота.
• Он шлет искателей в лагерь {link:dwarves}дворф{/link}ов, а затем в {link:hive-regal}Улей Регал{/link}, чтобы узнать судьбу своей возлюбленной.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна запись не говорит, как Мар'алит и {link:natalia-mar-alith}Наталия{/link} соединили свои жизни и как он стал командовать Крепостью.]=],
		},
	},
	chapters = {
		{
			title = "Ужасная цель",
			hint = "Принесите командиру тайны Сумеречного Молота.",
			text = [=[К нему попала табличка из разоренного лагеря культа, расшифрованная дезертиром культа. Она рассказывала о паломниках, которые собираются в {link:silithus}Силитус{/link}е, чтобы построить камень ветра и вызвать барона из числа повелителей элементалей. Для командира это была добыча. {link:nak}Нак{/link}онец он узнал, зачем {link:twilight-s-hammer}Сумеречный Молот{/link} пришел в пустыню, и мог обдумать свою борьбу с ним.]=],
		},
		{
			title = "Милая Наталия",
			hint = "Узнайте у дворфов, что сталось с возлюбленной командира.",
			text = [=[Неделями перед исчезновением {link:natalia-mar-alith}Наталия{/link} говорила сама с собой, когда думала, что рядом никого нет. Она настаивала, что все хорошо и что ее исследования должны продолжаться. В последний раз ее видели, когда она шла на юг, к лагерю {link:dwarves}дворф{/link}ов. То, что дворфы рассказали о ней, заставило командира опустить голову. Жива она или мертва, сказал он, ее нужно найти.]=],
		},
		{
			title = "В пасть безумия",
			hint = [=[Войдите в Улей Регал и узнайте судьбу жрицы Наталии Мар'алит.]=],
			text = [=[Он послал своего искателя в {link:hive-regal}Улей Регал{/link} с суровым приказом: если она и вправду сошла с ума, сделать то, что должно быть сделано. Потом он отвернулся. Когда искатель вернулся, командир услышал, чем стала {link:natalia-mar-alith}Наталия{/link}, и имя, которого он никогда не знал. Схватившись за грудь, он спросил, чем может быть этот К'Тун и как он мог сделать из нее чудовище.]=],
		},
	},
	mentions = {
		{ text = "«Ужасная цель»" },
		{ text = "«Милая {link:natalia-mar-alith}Наталия{/link}»" },
		{ text = "«В пасть безумия»" },
	},
	bonds = {
		{ id = "natalia-mar-alith", name = "Наталия Мар'алит", note = "его возлюбленная, пропавшая в улье" },
		{ id = "vish-kozus", name = "Виш Козус", note = "его капитан стражи" },
		{ id = "windcaller-proudhorn", name = "призыватель ветра Гордый Рог", note = "встречает рекрутов в его Крепости" },
		{ id = "hermit-ortell", name = "отшельник Ортелл", note = "прислал ему тайны культа" },
		{ id = "rutgar-glyphshaper", name = "Рутгар Резчик Символов", note = "рассказал о ее падении" },
	},
})

Translate("ruRU", "natalia-mar-alith", {
	title = "Наталия Мар'алит",
	subtitle = "Верховная жрица бога К'Туна",
	found = "Глубины Улья Регал",
	hint = [=[Ищите пропавшую возлюбленную командира в глубинах Улья Регал.]=],
	allegiance = "Прежде Круг Кенария · К'Тун",
	aliases = { "Госпожа Наталия Мар'алит", "Наталия" },
	sections = {
		{
			title = "Обзор",
			text = [=[Наталия Мар'алит была жрицей из ночных эльфов в Крепости Кенария и возлюбленной ее командира. Она первой из ночных эльфов Крепости присоединилась к {link:dwarves}дворф{/link}ам в их поисках в ульях. В Улье Регал она коснулась кристалла с глифами, и нечто коснулось ее в ответ. Теперь она носит титул верховной жрицы того, чье имя — {red:c-thun}К'Тун{/red}.]=],
		},
		{
			title = "Значение",
			text = [=[Падение жрицы показывает, что сила, запечатанная в Ан'Кираже, все еще может дотянуться до живых. Через нее {link:cenarion-circle}Круг Кенария{/link} впервые услышал имя К'Туна.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она присоединилась к Лиге исследователей в ее вылазках в ульи.
• Она впала в транс у кристалла с глифами в Улье Регал и очнулась под опекой друидов {link:krueg-skullsplitter}Круг{/link}а.
• Она обратилась против {link:dwarves}дворф{/link}ов в их лагере и бежала в {link:hive-regal}Улей Регал{/link} сквозь ряды силитидов.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ничего не написано о жизни жрицы до {link:silithus}Силитус{/link}а и об исследованиях, от которых она не желала отказаться.]=],
		},
	},
	chapters = {
		{
			title = "Кристалл в улье",
			hint = "Выслушайте рассказ дворфов о жрице.",
			text = [=[Когда {link:dwarves}дворф{/link}ы вынесли ее из Улья Регал, друиды {link:krueg-skullsplitter}Круг{/link}а привели ее в чувство, и несколько недель все казалось благополучным. Потом она вернулась в лагерь дворфов и потребовала, чтобы они немедля шли обратно в улей. {link:brann-bronzebeard}Бранн Бронзобород{/link} отказался идти без армии. Наталия заговорила на наречии, которого никто из них не знал, с кем-то, кого никто из них не видел. Потом она напала. Ее глаза светились, и она вгоняла сумрачные слова им в разум. Спасла их обезьянка предводителя. Наталия бежала в улей, и силитиды ее пропустили.]=],
		},
		{
			title = "Пасть безумия",
			hint = "Встретьте то, что ждет в Улье Регал.",
			text = [=[Искатель ее возлюбленного нашел ее глубоко в Улье Регал. Она больше не была той женщиной, что покинула {link:cenarion-hold}Крепость Кенария{/link}. Теперь она служила Древнему богу как его верховная жрица.]=],
		},
	},
	mentions = {
		{ text = "«Милая Наталия»" },
		{ text = "«В пасть безумия»" },
		{
			text = [=[«{link:uther-the-lightbringer}Утер{/link}янное письмо {link:brann-bronzebeard}Бранн{/link}а Бронзоборода», которое предостерегает о ней]=],
		},
	},
	bonds = {
		{ id = "commander-mar-alith", name = "командир Мар'алит", note = "ее возлюбленный" },
		{ id = "frankal-stonebridge", name = "Франкал Каменный Мост", note = "пережил ее нападение" },
		{ id = "rutgar-glyphshaper", name = "Рутгар Резчик Символов", note = "вынес ее из улья" },
		{ id = "glibb", name = "Глибб", note = "прогнал ее" },
	},
})

Translate("ruRU", "valstann-staghelm", {
	title = "Валстанн Олений Шлем",
	subtitle = "Сын верховного друида",
	found = "Пал в Деревне Южного Ветра, в Войну Зыбучих песков",
	hint = "Прочтите о войне, которую ночные эльфы вели в пустыне.",
	allegiance = "Ночные эльфы · войско, которое вел Фэндрал Олений Шлем",
	aliases = { "Валстанн" },
	sections = {
		{
			title = "Обзор",
			text = [=[Валстанн Олений Шлем был сыном и правой рукой {link:fandral-staghelm}Фэндрала Оленьего Шлема{/link}. Он сражался рядом с отцом в {link:war-of-the-shifting-sands}Войне Зыбучих песков{/link}, когда ночные эльфы пытались сдержать народ киражи в {link:silithus}Силитус{/link}е. Его послали оборонять Деревню Южного Ветра. Деревня пала, и Валстанн погиб.]=],
		},
		{
			title = "Значение",
			text = [=[Смерть сына — рана в самом сердце жизни верховного друида. Собственная книга ночных эльфов о войне утверждает, что события в {link:silithus}Силитус{/link}е во многом сделали его нрав таким горьким в поздние годы. Скипетр у преграды Ан'Киража швырнул наземь скорбящий отец.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он сражался вместе с отцом против роев Ан'Киража.
• Он отправился на защиту Деревни Южного Ветра и был схвачен, когда она пала.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись не называет ни возраста, в котором погиб Валстанн, ни его матери.]=],
		},
	},
	chapters = {
		{
			title = "Падение Южного Ветра",
			hint = "Пройдите среди руин, где пал сын верховного друида.",
			text = [=[{link:southwind-village}Южный Ветер{/link} был заставой ночных эльфов в восточной пустыне. Книга о войне говорит, что {link:fandral-staghelm}Фэндрал{/link} приказал сыну оборонять ее — и об этом выборе ему предстояло пожалеть. Дневник, найденный в руинах, говорит, что Валстанн, желая угодить отцу, сам попросился туда. Императоры-близнецы Ан'Киража спрятали свои армии под песком, и ловушку не разглядели. Деревня была уничтожена. Генерал Раджакс вывел пленника перед строем и убил его на глазах у отца. Руины стоят до сих пор, и по ним бродят духи друидов и часовых.]=],
		},
	},
	bonds = {
		{ id = "fandral-staghelm", name = "Фэндрал Олений Шлем", note = "его отец" },
	},
})

Translate("ruRU", "baristolth-of-the-shifting-sands", {
	title = "Баристольф из Зыбучих песков",
	subtitle = "Дозорный бронзовых драконов",
	found = "Крепость Кенария",
	hint = [=[Поговорите с дозорным Крепости Кенария, который помнит старую войну.]=],
	allegiance = "Бронзовые драконы · Крепость Кенария",
	aliases = { "Баристольф" },
	sections = {
		{
			title = "Обзор",
			text = [=[Баристольф из Зыбучих песков стоит в Крепости Кенария и смотрит в сторону ульев. Тысячу лет назад он лежал изувеченный и близкий к смерти. Некто великий один раз дохнул на его тело и ждал, пока пески времени исцеляли его раны. Потом на него был возложен долг оставаться дозорным столько, сколько он будет нужен. С тех пор длится его стража.]=],
		},
		{
			title = "Значение",
